<script>
  // Need to check how to better let people include their styles...
  // import style from '../scss/styles.scss?inline'
  import { onMount } from 'svelte'

  export let containers, increment, startAt
  export let useIFrame = false
  export let border = true

  // ========================
  // Configuration
  // ========================
  containers = containers || 10
  increment = increment || 50 // px
  startAt = startAt || 300 // px

  // ========================
  // Borders
  // ========================
  if (border) border = '1px var(--border-style) black'
  else border = 'none'

  // ========================
  // For Iframe
  // ========================
  let slotContainer
  let srcdoc

  if (useIFrame) {
    onMount(_ => {
      // For Astro Slots
      const slotContent = slotContainer.firstElementChild.firstElementChild
      if (!slotContent) return

      srcdoc = `
      <html>
        <body>
          ${slotContent.outerHTML}
        </body>
      </html>
    `
    })
  }

  function resetFrameHeight() {
    const iframe = this

    // Link Stylesheet
    const head = iframe.contentDocument.head
    const styleTag = document.createElement('style')
    styleTag.innerText = 'style'
    head.appendChild(styleTag)

    styleTag.onload = function () {
      const height = iframe.contentWindow.document.body.scrollHeight
      const iframePadding = 16
      iframe.style.height = height + iframePadding * 2 + 1 + 'px'
      iframe.style.padding = iframePadding + 'px'
      iframe.style.border = '1px var(--border-style) black'
    }
  }
</script>

<div class="CQCheckerGrid">
  {#each Array(containers).fill() as _, i}
    {@const width = i * increment + startAt + 'px'}
    <div class="CQContainer" style={`width: ${width};`}>
      {#if srcdoc}
        <div class="size">{width} (iframe mode)</div>
        <iframe
          title="{width} (iframe mode)"
          frameborder="0"
          {srcdoc}
          {width}
          on:load={resetFrameHeight}
        ></iframe>
      {:else}
        <div class="size">{width}</div>
        <div
          class="slotContent"
          style={` border: ${border}`}
          bind:this={slotContainer}
        >
          <slot />
        </div>
      {/if}
    </div>
  {/each}
</div>
